#   4회 미만 약어 금지, LLM 사용은 Methods에 기재, Vancouver 번호 인용, 단일 익명(본문 1쪽 제목면). 단독 저자 → 1인칭 금지. 결과 절에 해석 금지. 제목 쌍점 금지, 시리즈 제목 틀 반복 금지.
#  ★공변량은 "고혈압성질환 사망 역학 문헌에 근거해 고른 세트" — "pre-specified/before any model was fitted" 문구 금지.
#  ★역방향(중강도 신체활동): 주모형 그대로 + 사후 검정(88r)은 결과를 본 뒤 추가했음을 Methods에 명시, 해석은 Discussion.
from numbers_htnd import load, ROB, REV, RS
import os, math, pandas as pd
N = load()
NB = " "
def th(x, d=0):
    s = f"{x:,.{d}f}"; return s.replace(",", NB)
def tci(t): return f"MRR {t[0]:.3f}; 95% CrI {t[1]:.3f} to {t[2]:.3f}"
def ci(v): r = N["main"][v]; return tci((r["IRR"], r["lo"], r["hi"]))
M = N["main"]; T1 = N["T1"]
S43 = lambda a, v: N["s43"][(a, v)]
dW = lambda a: N["s43_waic"][a] - N["waic_main"]
NCO = lambda o, v: N["s41"][("H1_nco_" + o, v)]
S41 = lambda a, v: N["s41"][(a, v)]
S44 = lambda a, v: N["s44"][(a, v)]
S45 = lambda a, v: N["s45"][(a, v)]
SC = lambda s, v: N["sens_main"][s][v]
EN = {"강원도": "Gangwon", "충청남도": "South Chungcheong", "충청북도": "North Chungcheong", "경기도": "Gyeonggi", "서울시": "Seoul", "경상북도": "North Gyeongsang",
      "경상남도": "South Gyeongsang", "전라남도": "South Jeolla", "전라북도": "North Jeolla", "광주시": "Gwangju", "부산시": "Busan", "인천시": "Incheon", "울산시": "Ulsan",
      "대전시": "Daejeon", "세종시": "Sejong", "대구시": "Daegu", "제주도": "Jeju"}
def sidos(d, n):
    l = [f"{EN.get(k, k)} ({v})" for k, v in list(d.items())[:n]]; return ", ".join(l[:-1]) + " and " + l[-1]
KH = ("KH_typeI", "KH_typeII", "KH_typeIII", "KH_typeIV")
SHT, TRT, AWR, OBE, MDM, ALC = "screening_suspected_hypertension_share", "hypertension_treatment_rate", "bp_awareness_rate", "screening_abdominal_obesity_share", "screening_suspected_diabetes_share", "high_risk_drinking_rate"
WALK, MPA, FAC = "walking_practice_rate", "moderate_pa_rate", "public_sports_facilities_per_100k"
BLS, IMS, OLD = "basic_livelihood_rate", "im_specialists_per_100k", "older_single_household_share"
TITLE = "Hypertensive disease mortality across Korean districts"
assert ":" not in TITLE and "2011" not in TITLE and "229" not in TITLE and "standardi" not in TITLE.lower() and len(TITLE) <= 150 and not TITLE.startswith(("Do ", "Does ", "Which ", "Persistent", "Age-", "District"))
RUNNING = "Hypertensive disease deaths in Busan"
_LK = pd.read_csv(os.path.join(RS, "S1_likelihood.csv")); _LK = _LK[_LK.set == "REF_forced_only"].set_index("family").WAIC
_FAM = pd.read_csv(os.path.join(RS, "S3_main_fit.csv")).family.iloc[0]
assert _FAM == "nbinomial" and _LK["nbinomial"] < _LK["poisson"] and abs(_LK["nbinomial"] - N["waic_forced"]) < 0.15
NHYP = N["n_hyp"]; EXP_CHANCE = 0.05 * NHYP; assert NHYP == 12
SUP = {"methods": "Supplementary Methods", "covariates": "Supplementary Table S1", "datacheck": "Supplementary Table S2", "specs": "Supplementary Table S3", "coding": "Supplementary Table S4", "reverse": "Supplementary Table S5", "regions": "Supplementary Table S6", "persistence": "Supplementary Fig. S1", "strobe": "Supplementary Checklist"}
def sup(k): return SUP[k]
WN = ("W1_2011-15", "W2_2016-19", "W3_2020-24")
_W = pd.read_csv(os.path.join(RS, "S4_window_IRR.csv")).set_index(["cov", "window"])
def wt(v, w): r = _W.loc[(v, w)]; return (r.IRR, r.lo, r.hi, bool(r.cred))
RET = N["ret14"]; NALT = RET[MPA][1]
def ret(v):
    sg = N["main"][v]["IRR"] > 1; rr = [N["s41"][(a, v)] for a in N["alt14"] if (a, v) in N["s41"]]
    return sum(1 for t in rr if t[3] and (t[0] > 1) == sg), len(rr)
BEST = min(KH, key=lambda a: N["s43_waic"][a]); assert BEST == "KH_typeII"
BW = lambda v, part: N["bw"][f"{v}__{part}"]
_hot = N["type_class"]["hotspot"]; _cold = N["type_class"]["coldspot"]; _nt = N["n_type"]
_NC = lambda v: tci((N["negctl"][v]["IRR"], N["negctl"][v]["lo"], N["negctl"][v]["hi"]))
VP = N["varpart"]; VSP = VP["spatial_structured"]["share_of_sum"]; VCOV = VP["fixed_covariates"]["share_of_sum"]; VHYP = VP["fixed_hypothesis"]["share_of_sum"]
R4 = lambda v: S44("R4_single_" + v, v)
CS = N["circ_share"]; AC = N["asr_circ"]; A = N["asr"]
SMR = N["sido_smr"]
_PPC = float(__import__("decimal").Decimal(str(100 * N["ppc"]["coverage95"])).quantize(__import__("decimal").Decimal("0.1"), rounding="ROUND_HALF_UP"))
_PER = N["persist_hot_list"]; _per_s = pd.Series([x[:3] for x in _PER]).value_counts().to_dict()
_SE = sum(_per_s.get(k, 0) for k in ("부산시", "울산시", "경상북", "경상남", "대구시"))

METHODS = [
("Design, outcome and population",
 f"This ecological study used annual deaths from hypertensive diseases (International Classification of Diseases, 10th revision, I10-I13: essential hypertension and hypertensive heart, kidney, and heart and kidney disease) in 2011-2024 by district of residence from the national cause-of-death statistics of Statistics Korea, which cover all registered deaths [@web:kostat2026cause]. Data were extracted in November 2026. Districts were harmonized to {N['n_districts']} units with 2024 boundaries ({th(N['n_rows'])} district-years), with resident populations by 5-year age group as denominators [@web:mois2026population] ({sup('methods')})."),
("Age standardization",
 "Expected deaths were obtained by indirect standardization: national age-specific death rates from hypertensive diseases in eighteen 5-year groups up to 85 years or older were applied to each district's age structure each year, and expected deaths were rescaled so that their national total equaled observed deaths [@inskip1983methods]. Observed over expected deaths gives the standardized mortality ratio. National trends were directly standardized to the 2015 population. Because the oldest group was open-ended, the share aged 80 years or older was also included as a forced control; a sensitivity analysis standardized by sex and age."),
("District characteristics",
 f"Twelve district characteristics were selected on the basis of the epidemiological literature on blood pressure, its control, and hypertensive disease mortality [@lewington2002age; @ncdrisc2021worldwide; @park2016spatial], within the limits of annually available district series. The blood pressure care cascade was represented by the share of attendees of the national general health screening with suspected hypertension on measured blood pressure among those not already classified as under treatment, the treatment rate among adults with diagnosed hypertension, and awareness of one's own blood pressure value; cardiometabolic risk by the screening shares of abdominal obesity (waist circumference) and suspected diabetes (fasting glucose) and by high-risk drinking; physical activity by walking practice, moderate-or-higher-intensity physical activity, and public sports facilities per 100{NB}000 population; and structural conditions and access by the share of residents receiving basic livelihood security benefits (the national means-tested public assistance program), internal medicine specialists per 100{NB}000 population, and households of older adults living alone. Survey indicators were district age-standardized rates among adults from the Community Health Survey [@kang2015korea]. Measured screening values were used instead of self-reported diagnosis, which reflects diagnosis and awareness as much as prevalence [@lee2019temporal]. Low-salt preference, the only district sodium indicator, was not surveyed after 2019, and so was examined in a sensitivity analysis restricted to 2011-2019 rather than in the principal model. Expected directions, sources, observed years, and filled cells are listed in {sup('covariates')}, and panel checks before modeling in {sup('datacheck')}. Five controls were forced into every model: urban population share, physician density, sex ratio, fiscal autonomy, and the share aged 80 years or older. Covariates were standardized to 1 standard deviation, and missing years were filled within districts."),
("Statistical analysis",
 f"The likelihood was chosen by the lower widely applicable information criterion (WAIC) of the forced-controls model (negative binomial). Models had an offset of log expected deaths, a Besag-York-Mollié 2 district effect on a contact graph of 593 neighboring district pairs, with island districts linked to the nearest mainland districts, and penalized-complexity priors [@riebler2016intuitive; @simpson2017penalising], and random-walk and independent year effects, fitted by integrated nested Laplace approximation [@rue2009approximate] in R [@web:rcore2026]. Mortality rate ratios (MRRs) per 1 standard deviation are reported with 95% credible intervals (CrIs); an association was credible when the interval excluded 1. Intervals were not adjusted for multiplicity; with {NHYP} characteristics and independent null associations, about {EXP_CHANCE:.1f} would be expected to exclude 1 by chance, and the analysis is exploratory. Sensitivity to covariate selection was assessed with 200 random covariate subsets (subset-stable: interval excluding 1 in at least 75% of subsets containing the characteristic, same sign in at least 95%). Because subset fits share one model structure, structural checks were given priority: Knorr-Held type I-IV space-time interactions, of which types II and IV allow each district its own trend [@knorrheld2000bayesian], and a province-by-year effect. Subset-stable characteristics were split into district means and two-way-centered within-district deviations [@bell2015explaining]. Fourteen alternative specifications ({sup('specs')}) varied the likelihood, time effects, smoothing, lags, extreme values, survey averaging, and years included; further checks varied neighborhoods, priors, and age grouping, added a Spatial+-type adjustment [@dupont2022spatial], left out each province or year, perturbed filled values 20 times, and refitted the principal model by window and to two comparison outcomes (transport accident deaths and people treated for infectious diseases). Hit-and-run accidents, a traffic culture index, and fires served as negative-control exposures. Residual hot and cold spots had a posterior probability of a residual spatial rate ratio above 1 greater than 0.95 or less than 0.05; these descriptive classifications were not corrected for multiple comparisons. The variance of the linear predictor was partitioned into spatial, temporal, and covariate components; because components covary, their shares are not proportions of explained variance."),
("Death certification",
 f"Deaths of people with hypertension may be certified to hypertensive disease or to heart failure, stroke, or ischemic heart disease, and redistributing heart failure deaths shifts them toward coronary and hypertensive heart disease [@snyder2014redistribution]. The national share of circulatory deaths (I00-I99) certified as hypertensive was therefore tracked, and the principal model was refitted with all circulatory deaths as the outcome (expected deaths from national circulatory death rates in the same age groups), with and without the share of deaths from ill-defined causes (R00-R99) as a marker of certification quality, and with the out-of-district outpatient share as a marker of access ({sup('coding')}). District residual spatial rate ratios (posterior means) were compared between the two outcomes, and for Busan their range and average across the 16 districts are reported."),
("Checks added after results were seen",
 f"Moderate-or-higher physical activity was credible in the direction opposite to that expected. The principal model was kept, and post hoc checks fitted it with the forced controls alone and without the other physical activity characteristics ({sup('reverse')}). After the results were seen, further analyses were added: the principal model refitted to circulatory deaths excluding hypertensive diseases (expected deaths as the difference between circulatory and hypertensive expected deaths); a model with the forced controls only, to compare residual spatial rate ratios before and after the 12 characteristics; residual spatial rate ratios of Busan districts after adding the ill-defined cause share; and an age-standardized comparison of hypertensive with circulatory mortality in Busan ({sup('coding')})."),
("Ethics, reporting and use of large language models",
 "The study used only published aggregate statistics. The Institutional Review Board of Hongik University approved the study on November 4, 2025 (7002340-202511-HR-012) and its continuing review on November 3, 2026 (7002340-202611-HR-040), and waived informed consent because no individual-level data were used. Reporting follows the Strengthening the Reporting of Observational Studies in Epidemiology statement [@vonelm2007strengthening] (" + SUP["strobe"] + "). The author used Claude (Anthropic) and ChatGPT (OpenAI) only for translation and English-language editing of the manuscript."),
]

_att = lambda a, v: 100 * math.log(S43(a, v)[0]) / math.log(M[v]["IRR"])
RESULTS = [
("Deaths, trends and certification",
 f"Over 2011-2024, {th(N['cases_total'])} deaths from hypertensive diseases occurred in {N['py']/1e6:.0f} million person-years; annual deaths rose from {th(N['cases_2011'])} to {th(N['cases_2024'])}, and the share at ages 85 years or older from {100*N['share85_2011']:.1f}% to {100*N['share85_2024']:.1f}%; Table 1 summarizes deaths and district characteristics by window. The directly age-standardized rate fell from {A[2011]:.1f} per 100{NB}000 in 2011 to {A[2021]:.1f} in 2021, rose to {A[2022]:.1f} in 2022, and was {A[2024]:.1f} in 2024 (ratio 2024 to 2011, {N['asr_ratio']:.2f}), whereas the age-standardized rate of all circulatory deaths fell from {AC[2011]:.1f} to {AC[2024]:.1f} (ratio {AC[2024]/AC[2011]:.2f}). The share of circulatory deaths certified as hypertensive rose from {100*CS[2011]:.1f}% in 2011 to {100*CS[2021]:.1f}% in 2021, {100*CS[2022]:.1f}% in 2022, and {100*CS[2024]:.1f}% in 2024, and the ratio of the age-standardized hypertensive to circulatory rate from {100*N['asr_share'][2011]:.1f}% to {100*N['asr_share'][2024]:.1f}% (Fig. 1)."),
("Geography",
 f"Moran's I was {N['moran_pooled']:.2f} for pooled log standardized mortality ratios and ranged from {N['moran_year_min']:.2f} to {N['moran_year_max']:.2f} by year; the spatial fraction of the district effect was {N['phi'][0]:.2f} (95% CrI {N['phi'][1]:.2f} to {N['phi'][2]:.2f}). Over the whole period, {N['n_hot']} districts were residual hot spots, mainly in {sidos(N['hot_by_sido'], 6)}; all {N['busan_n']} districts of Busan were hot spots, with residual spatial rate ratios of {N['busan_rr_main'][0]:.2f} to {N['busan_rr_main'][1]:.2f}. With a posterior probability above 0.99, {N['hot_strict'][0.99][0]} districts were hot spots. Cold spots numbered {N['n_cold']}, the largest number ({N['cold_by_sido']['서울시']}) in Seoul (Fig. 2). The pooled standardized mortality ratio was {SMR['부산시']:.2f} in Busan, {SMR['울산시']:.2f} in Ulsan, and {SMR['서울시']:.2f} in Seoul. In window-specific models, {N['hot_all_windows']} districts were hot spots in all three windows, {_SE} of them in the southeastern provinces and cities ({_per_s.get('울산시',0)} in Ulsan and {_per_s.get('부산시',0)} in Busan), and Kendall's W for annual district rankings was {N['kendall_W']:.2f} ({sup('persistence')})."),
("District characteristics",
 f"Adding the {NHYP} characteristics changed WAIC from {th(N['waic_forced'],1)} to {th(N['waic_main'],1)}. Mortality was lower with more internal medicine specialists ({ci(IMS)}) and, opposite to expectation, higher with more moderate-or-higher physical activity ({ci(MPA)}) (Table 2). Suspected hypertension on screening ({ci(SHT)}), treatment among diagnosed adults ({ci(TRT)}), blood pressure awareness ({ci(AWR)}), abdominal obesity ({ci(OBE)}), suspected diabetes ({ci(MDM)}), high-risk drinking ({ci(ALC)}), walking ({ci(WALK)}), sports facilities ({ci(FAC)}), basic livelihood recipients ({ci(BLS)}), and older adults living alone ({ci(OLD)}) were not credibly associated. Of the negative-control exposures, fires were credibly associated ({_NC('fires_per_10000')}), whereas hit-and-run accidents ({_NC('hit_and_run_rate')}) and the traffic culture index ({_NC('traffic_culture_index')}) were not. Of the summed variance components of the linear predictor, structured spatial variation contributed {100*VSP:.0f}%, the {NHYP} characteristics {100*VHYP:.0f}%, and the forced controls {100*VP['fixed_forced_controls']['share_of_sum']:.0f}%."),
("Robustness",
 f"Only moderate-or-higher physical activity was subset-stable (credible in {100*N['mv'][MPA]['cred_frac']:.0f}% of subset fits); internal medicine specialists were credible in {100*N['mv'][IMS]['cred_frac']:.0f}%. Models allowing district-specific trends fitted better (Fig. 3; ΔWAIC {th(dW('KH_typeII'))} for type II and {th(dW('KH_typeIV'))} for type IV), and in them neither association was credible (type II: {tci(S43('KH_typeII', MPA))} for physical activity and {tci(S43('KH_typeII', IMS))} for specialists), nor with province-by-year effects; basic livelihood recipients became credible in the type II model ({tci(S43('KH_typeII', BLS))}). Physical activity was not credible in any calendar window and was credible in {RET[MPA][0]} of {NALT} alternative specifications, and specialists in {ret(IMS)[0]} of {NALT}, including 1-year ({tci(S41('E1_lag1', IMS))}) and 2-year lags ({tci(S41('E2_lag2', IMS))}) and the Spatial+-type adjustment ({tci(S41('D1_spatial_plus', IMS))}). Basic livelihood recipients were credible in {ret(BLS)[0]} of {NALT} alternative specifications and in 2011-2015 ({tci(wt(BLS, WN[0])[:3])}) and 2016-2019 ({tci(wt(BLS, WN[1])[:3])}) but not in 2020-2024 ({tci(wt(BLS, WN[2])[:3])}). Residual Moran's I was {N['moran_resid']:.2f}, and posterior predictive 95% intervals covered {_PPC:.1f}% of district-years ({sup('specs')})."),
("Certification checks",
 f"With all circulatory deaths as the outcome, district residual spatial rate ratios correlated with those for hypertensive diseases (Spearman ρ {N['rr_main_broad_rho']:.2f}), {N['broad_hot']} districts were hot spots, and all {N['busan_n']} Busan districts remained hot spots, with ratios of {N['busan_rr_broad'][0]:.2f} to {N['busan_rr_broad'][1]:.2f} (Fig. 2). In that model, blood pressure awareness ({tci(S45('Z2_broad_outcome', AWR))}) and suspected diabetes ({tci(S45('Z2_broad_outcome', MDM))}) were credibly associated. With circulatory deaths excluding hypertensive diseases, all {N['busan_n']} Busan districts were again hot spots ({N['busan_rr_nonhtn'][0]:.2f} to {N['busan_rr_nonhtn'][1]:.2f}). Hypertensive diseases accounted for {100*N['busan_htn_share']:.1f}% of circulatory deaths in Busan and {100*N['rest_htn_share']:.1f}% elsewhere; with age standardization, the ratio of the hypertensive to the circulatory standardized mortality ratio was {N['smr_ratio'][True]:.2f} in Busan and {N['smr_ratio'][False]:.2f} elsewhere. Ill-defined causes accounted for {100*N['busan_illdef']:.1f}% of all deaths in Busan and {100*N['rest_illdef']:.1f}% elsewhere. With the ill-defined cause share added, the residual spatial rate ratios of Busan districts ranged from {N['busan_ill']['htnd'][0]:.2f} to {N['busan_ill']['htnd'][1]:.2f} for hypertensive diseases (average {N['busan_ill']['htnd'][2]:.2f}; {N['busan_ill']['htnd'][3]} hot spots) and from {N['busan_ill']['circ'][0]:.2f} to {N['busan_ill']['circ'][1]:.2f} for all circulatory deaths (average {N['busan_ill']['circ'][2]:.2f}; {N['busan_ill']['circ'][3]} hot spots), compared with averages of {N['busan_mean_rr']['RR_main']:.2f} and {N['busan_broad_mean']:.2f} without it. With the forced controls only, the residual spatial rate ratios of Busan districts ranged from {N['busan_rr_forced'][0]:.2f} to {N['busan_rr_forced'][1]:.2f} (average {N['busan_mean_rr']['RR_forced']:.2f}), and after the 12 characteristics were added from {N['busan_rr_main'][0]:.2f} to {N['busan_rr_main'][1]:.2f} (average {N['busan_mean_rr']['RR_main']:.2f}). Adding the ill-defined cause share to the principal model, which was itself associated with fewer hypertensive deaths ({tci(S45('Z1_illdefined', 'ill_defined_death_share'))}), made suspected hypertension ({tci(S45('Z1_illdefined', SHT))}) and basic livelihood recipients ({tci(S45('Z1_illdefined', BLS))}) credible. For transport accident deaths, basic livelihood recipients ({tci(NCO('TRANS', BLS))}) and suspected hypertension ({tci(NCO('TRANS', SHT))}) were credibly associated. Low-salt preference in 2011-2019 was not associated ({tci(S45('Z5_low_salt_2011_2019', 'low_salt_preference_rate'))}) ({sup('coding')})."),
("Physical activity, opposite to the expected direction",
 f"For physical activity, the within-district component (two-way-centered deviation) was credible ({tci(BW(MPA, 'within'))}) and the between-district component was not ({tci(BW(MPA, 'between'))}); the two were not formally compared. The association persisted with the forced controls alone ({tci(R4(MPA))}) and without walking and sports facilities ({tci(S44('R5_drop_other_activity', MPA))}) and was not credible for transport accident deaths or infectious disease care ({sup('reverse')}). Region-specific slopes did not improve fit (ΔWAIC {N['s50_region_dwaic'][MPA]:.1f}); the region-specific estimate excluded 1 only in the capital region ({tci(N['s50_region'][(MPA, 'Capital')][:3])}) ({sup('regions')})."),
]

# 문장 주장 대조(결과표와 어긋나면 빌드 중단)
H = [v for v in M if M[v]["role"] == "hypothesis"]
assert {v for v in H if M[v]["cred"]} == {MPA, IMS} and M[MPA]["IRR"] > 1 and M[IMS]["IRR"] < 1 and N["waic_main"] > N["waic_forced"] and set(ROB) == {MPA} and set(REV) == {MPA}
assert N["negctl"]["fires_per_10000"]["cred"] and not N["negctl"]["hit_and_run_rate"]["cred"] and not N["negctl"]["traffic_culture_index"]["cred"]
assert not any(S43(a, v)[3] for a in ("KH_typeII", "KH_typeIV") for v in (MPA, IMS)) and not any(S41("C4_sido_year_iid", v)[3] for v in (MPA, IMS))
assert sorted(v for v in H if S43("KH_typeII", v)[3]) == [BLS] and dW("KH_typeII") < 0 and dW("KH_typeIV") < 0
assert not any(wt(MPA, w)[3] for w in WN) and wt(BLS, WN[0])[3] and wt(BLS, WN[1])[3] and not wt(BLS, WN[2])[3]
assert S41("E1_lag1", IMS)[3] and S41("E2_lag2", IMS)[3] and S41("D1_spatial_plus", IMS)[3]
assert BW(MPA, "within")[3] and not BW(MPA, "between")[3] and R4(MPA)[3] and S44("R5_drop_other_activity", MPA)[3]
assert N["s50_region"][(MPA, "Capital")][3] and not any(N["s50_region"][(MPA, r)][3] for r in ("Yeongnam", "Honam", "Chungcheong", "Gangwon_Jeju"))
assert not NCO("TRANS", MPA)[3] and not NCO("INFECT", MPA)[3]
assert N["busan_hot"] == 16 and N["broad_hot_busan"] == 16 and N["busan_broad_p"] > 0.99 and N["busan_nonhtn_hot"] == 16 and N["busan_rr_forced"][0] < N["busan_rr_main"][0] + 0.05 and abs(N["busan_htn_share"] - N["rest_htn_share"]) < 0.01 and N["busan_illdef"] < N["rest_illdef"]
assert S45("Z2_broad_outcome", AWR)[3] and S45("Z2_broad_outcome", MDM)[3] and not S45("Z2_broad_outcome", MPA)[3] and not S45("Z2_broad_outcome", IMS)[3]
assert S45("Z1_illdefined", "ill_defined_death_share")[3] and S45("Z1_illdefined", "ill_defined_death_share")[0] < 1 and S45("Z1_illdefined", SHT)[3] and S45("Z1_illdefined", BLS)[3]
assert not S45("Z5_low_salt_2011_2019", "low_salt_preference_rate")[3]
assert A[2021] == min(A.values()) and A[2022] > A[2021] and CS[2024] > CS[2011] and AC[2024] < AC[2011]
assert not any(M[v]["cred"] for v in (SHT, TRT, AWR, OBE, MDM, ALC, WALK, FAC, BLS, OLD))

if __name__ == "__main__":
    import re
    for h, t in METHODS + RESULTS: print("##", h, "\n", t, "\n")
    print("words M", sum(len(re.sub(r"\[@[^\]]+\]", "", t).split()) for _, t in METHODS), "R", sum(len(re.sub(r"\[@[^\]]+\]", "", t).split()) for _, t in RESULTS))
